struct Target final:IDurableMutationTarget3D{bool fail{};int prepares{},commits{},aborts{};WorldChunkDeltaSnapshot3D value{};bool Prepare(std::uint64_t,const WorldChunkDeltaSnapshot3D&v)override{++prepares;if(fail)return false;value=v;return true;}void Commit(std::uint64_t,const WorldChunkDeltaSnapshot3D&v)noexcept override{++commits;value=v;}void Abort(std::uint64_t)noexcept override{++aborts;}};
int main(){SceneECSRegistry3D scene;ReplicatedSceneRegistry3D replicated(scene);SceneEntityDefinition3D definition{};definition.transform=SceneTransformComponent3D{{{1,2,3},{},{1,1,1}}};std::array<std::pair<NetworkEntityId3D,SceneEntityDefinition3D>,2> definitions{{{{1,1},definition},{{1,2},definition}}};WorldOrigin3D origin{};if(!replicated.SpawnAtomic(definitions,origin)||!replicated.Query({1,1})||scene.Stats().aliveEntities)return 1;if(!replicated.Apply({1,1},{{-2,0,3},{31,4,5}},10,origin)||replicated.Apply({1,1},{},9,origin))return 2;auto state=replicated.Query({1,1});if(!state||state->tick!=10||!replicated.DespawnAtomic(std::array<NetworkEntityId3D,1>{{1,2}})||replicated.Query({1,2}))return 3;replicated.Clear();if(replicated.Query({1,1}))return 4;
 ReplicationChunkInterest3D interest({1,2,32});ReplicationInterestDelta3D delta;if(!interest.Update({{-1,0,-1},{31,0,31}},delta)||delta.entered.size()!=9||delta.epoch!=1)return 5;if(!interest.Update({{3,0,0},{0,0,0}},delta)||delta.left.empty()||delta.entered.empty())return 6;
 const auto root=std::filesystem::temp_directory_path()/"aevrynd-replication-authority";std::error_code error;std::filesystem::remove_all(root,error);WorldDeltaStoreSettings3D storeSettings{};storeSettings.root=root;storeSettings.maximumSnapshotBytes=1<<20;storeSettings.maximumQueuedBytes=4<<20;storeSettings.maximumCompletedBytes=5<<20;WorldChunkDeltaStore3D store(storeSettings);Target target;DurableMutationAuthority3D authority(store,target,{55,4,8});WorldChunkDeltaSnapshot3D snapshot{};snapshot.key={{7,8},1,1,{-2,0,4}};snapshot.base={1,1,1,1,{}};snapshot.durableGeneration=1;ReplicationMutationRequest3D request{55,99,2,snapshot.key,{0,0,0,{},RemoveVegetationDelta3D{{10,11}}}};if(!authority.Submit(request,snapshot,42)||target.commits){std::cerr<<"submit failed rejected="<<authority.Stats().rejected<<" prepares="<<target.prepares<<" aborts="<<target.aborts<<" storeRejected="<<store.Stats().rejected<<'\n';return 7;}store.WaitIdle();authority.Poll();ReplicationMutationReceipt3D receipt;if(!authority.TryPopReceipt(receipt)||!receipt.accepted||!receipt.durable||receipt.serverTick!=42||target.commits!=1||target.value.operations.size()!=1)return 8;
 snapshot=target.value;auto commitOperation=[&](std::uint64_t id,std::uint32_t client,WorldChunkDeltaPayload3D payload){ReplicationMutationRequest3D next{55,id,client,snapshot.key,{0,0,0,{},std::move(payload)}};if(!authority.Submit(next,snapshot,42+id))return false;store.WaitIdle();authority.Poll();ReplicationMutationReceipt3D result;if(!authority.TryPopReceipt(result)||!result.durable)return false;snapshot=target.value;return true;};PersistentBuilding3D building{{20,21},44,55,{{-2,0,4},{2,3,4}},{},{1,1,1},1};if(!commitOperation(100,1,PlaceBuildingDelta3D{building})||!commitOperation(101,2,SetTerrainHeightDelta3D{3,4,8.5f})||!commitOperation(102,2,RemoveBuildingDelta3D{building.id}))return 9;
 WorldChunkDeltaStore3D restarted(storeSettings);if(!restarted.EnqueueLoad(5,1,snapshot.key,snapshot.base))return 10;restarted.WaitIdle();WorldDeltaLoadResult3D load;if(!restarted.TryPopLoad(load)||load.status!=WorldDeltaLoadStatus3D::Loaded||load.snapshot.lastSequence!=4||load.snapshot.operations.size()!=4)return 11;
 Target blocked;blocked.fail=true;DurableMutationAuthority3D rejected(store,blocked,{56,4,8});request.sessionEpoch=56;request.clientRequestId=200;if(rejected.Submit(request,snapshot,43)||blocked.commits||blocked.aborts!=1)return 12;
 // 已完成的相同request必回相同receipt，不能再次提交世界操作。
 if(!authority.Submit(ReplicationMutationRequest3D{55,99,2,snapshot.key,request.operation},snapshot,44))return 13;ReplicationMutationReceipt3D duplicate;if(!authority.TryPopReceipt(duplicate)||duplicate.sequence!=receipt.sequence||authority.Stats().duplicates!=1||target.commits!=4)return 14;
 // disabled store模擬持久層backpressure：Prepare後必Abort，gameplay Commit維持零。
 WorldDeltaStoreSettings3D disabledSettings=storeSettings;disabledSettings.root=root/"disabled";disabledSettings.enabled=false;WorldChunkDeltaStore3D disabledStore(disabledSettings);Target backpressure;DurableMutationAuthority3D unavailable(disabledStore,backpressure,{57,4,8});request.sessionEpoch=57;request.clientRequestId=201;if(unavailable.Submit(request,snapshot,45)||backpressure.prepares!=1||backpressure.aborts!=1||backpressure.commits)return 15;
 std::filesystem::remove_all(root,error);std::cout<<"interestEntered=9 committed="<<target.commits<<" sequence="<<receipt.sequence<<'\n';return 0;}
